LQ_INT32_Q15 LQ_INT32_Q15_SIN_PU_16384_SUBDIVIDE(LQ_INT32_Q15 A_Pu, LQ_ERROR* Lq_Error)
{
    //!<A+PI并去除符号位
    LQ_UI_32BIT uhindex = (LQ_UI_32BIT)((LQ_I_64BIT)2147483648 + (LQ_I_64BIT)A_Pu);
    //!<匹配表
    uhindex = uhindex >> 18;
    //!<获取编码标志位
    switch ((LQ_UI_32BIT)(uhindex) & (0x3000u))
    {
    case 0x2000u:
        return (LQ_INT32_Q15_SIN_COS_PU_16384_SUBDIVIDE_TABLE[(uhindex & 0x0FFFu)]);
    case 0x3000u:
        return (LQ_INT32_Q15_SIN_COS_PU_16384_SUBDIVIDE_TABLE[0x0FFFu - (uhindex & 0x0FFFu)]);
    case 0x0000u:
        return (-LQ_INT32_Q15_SIN_COS_PU_16384_SUBDIVIDE_TABLE[(uhindex & 0x0FFFu)]);
    case 0x1000u:
        return (-LQ_INT32_Q15_SIN_COS_PU_16384_SUBDIVIDE_TABLE[0x0FFFu - (uhindex & 0x0FFFu)]);
    default:
        (*Lq_Error) = INT32_Q15_SIN_PU_16384_SUBDIVIDE_UNABLE_TO_PARSE;
        break;
    }
    return 0;
}
